def normalize_toc_item(md: 'Markdown', token: Dict[str, Any]) ->Tuple[int,
    str, str]:
    children = token['children']
    text = md.renderer.render_children(token)
    plain = striptags(text)
    level = token['attrs']['level']
    tid = token['attrs']['id']
    return level, tid, plain

def render_toc_ul(toc: Iterable[Tuple[int, str, str]]) ->str:
    if not toc:
        return ''

    items = list(toc)
    first_level = items[0][0]

    def _render(items, current_level):
        result = '<ul>\n'
        i = 0
        while i < len(items):
            level, tid, text = items[i]
            if level == current_level:
                result += f'<li><a href="#{tid}">{text}</a>'
                if i + 1 < len(items) and items[i + 1][0] > current_level:
                    sub_items = []
                    j = i + 1
                    while j < len(items) and items[j][0] > current_level:
                        sub_items.append(items[j])
                        j += 1
                    result += '\n' + _render(sub_items, sub_items[0][0])
                    i = j
                else:
                    i += 1
                result += '</li>\n'
            else:
                i += 1
        result += '</ul>\n'
        return result

    return _render(items, first_level)
